use cliphost_core::text_actions;
use serde_json::Value;

#[test]
fn text_transforms_match_csharp_reference() {
    // Generated by invoking the actual BetterClip.Backend.Core
    // TextActionTransformPolicy.cs in .NET, not by the Rust implementation.
    let cases: Vec<Value> =
        serde_json::from_str(include_str!("fixtures/text-transform-csharp.json")).unwrap();
    check_csharp_cases(&cases);
}

#[test]
fn ecmascript_transforms_match_csharp_reference() {
    let cases: Vec<Value> = serde_json::from_str(include_str!(
        "fixtures/text-transform-ecmascript-csharp.json"
    )).unwrap();
    check_csharp_cases(&cases);
}

fn check_csharp_cases(cases: &[Value]) {
    let mut failures = Vec::new();
    for case in cases {
        let actual = text_actions::apply(&case["action"], case["text"].as_str().unwrap());
        let matches = if case["error"].is_string() {
            actual.is_err()
        } else {
            actual.as_deref().ok() == case["expected"].as_str()
        };
        if !matches {
            failures.push(format!(
                "{}: expected {:?}, got {actual:?}",
                case["name"], case["expected"]
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} / {} C# reference cases differ:\n{}",
        failures.len(),
        cases.len(),
        failures.join("\n")
    );
}

#[test]
fn unsupported_regex_options_cannot_silently_produce_different_text() {
    for option in [128, 2048] {
        let result = text_actions::apply(
            &serde_json::json!({
                "Type": "SingleReplace",
                "Data": {"Pattern":"a+", "ReplaceMent":"[$&]", "UseRegex":true, "Options":option}
            }),
            "aaa",
        );
        assert!(
            result.is_err(),
            "Regex option {option} was silently ignored"
        );
    }
}

#[test]
fn advanced_regex_runtime_limits_report_failure_instead_of_partial_replacement() {
    for pattern in [
        r"^(a|aa)+\1$",
        r"(?=(a))^(a|aa)+b$",
        r"^(?:(?<n>a)|(?<n>aa))+b$",
        r"^(?<n>a)?(?(n)(a|aa)+b|c)$",
        r"^(?<n>a)(?<-n>)(a|aa)+b$",
    ] {
        let error = text_actions::apply(&serde_json::json!({
            "Type":"SingleReplace", "Data":{"Pattern":pattern, "ReplaceMent":"changed", "UseRegex":true}
        }), &format!("{}!", "a".repeat(32))).unwrap_err();
        assert!(error.contains("已停止替换"), "{error}");
    }
}

#[test]
fn duplicate_names_share_the_same_dotnet_number() {
    let result = text_actions::apply(&serde_json::json!({
        "Type":"SingleReplace", "Data":{"Pattern":"(?<n>a)(?<n>b)(?=c)", "ReplaceMent":"$1/${n}", "UseRegex":true}
    }), "abc").unwrap();
    assert_eq!(result, "b/bc");
}

#[test]
fn nonbacktracking_preserves_long_near_misses_without_backtracking_limits() {
    let text = format!("{}!", "a".repeat(100_000));
    for pattern in [r"^(a|aa)+b$", r"^(?:(?<n>a)|(?<n>aa))+b$"] {
        let result = text_actions::apply(
            &serde_json::json!({
                "Type":"SingleReplace",
                "Data":{"Pattern":pattern, "ReplaceMent":"changed", "UseRegex":true, "Options":1024}
            }),
            &text,
        )
        .unwrap();
        assert_eq!(result, text);
    }
}

#[test]
fn balancing_repeated_captures_pop_without_copying_the_entire_history() {
    let text = format!("{}{}", "甲".repeat(10_000), "乙".repeat(10_000));
    let result = text_actions::apply(
        &serde_json::json!({
            "Type":"SingleReplace",
            "Data":{"Pattern":r"^(?<x>甲){10000}(?<-x>乙){10000}(?(x)(?!))$",
                "ReplaceMent":"balanced", "UseRegex":true}
        }),
        &text,
    )
    .unwrap();
    assert_eq!(result, "balanced");

    // Reuse the input coordinate map across matches as well as keeping each
    // match's capture history independent from previous ones.
    let result = text_actions::apply(
        &serde_json::json!({
            "Type":"SingleReplace",
            "Data":{"Pattern":r"(?<x>甲)😀(?<gap-x>乙)",
                "ReplaceMent":"${gap}", "UseRegex":true}
        }),
        &"甲😀乙".repeat(10_000),
    )
    .unwrap();
    assert_eq!(result, "😀".repeat(10_000));
}
